#include <bits/stdc++.h>
using namespace std;
int main(int c, char** v) { ifstream in(v[1]), out(v[2]), ans(v[3]); int n, m1, m2; in >> n >> m1 >> m2; vector<int> a(n + 1), b(n + 1); iota(a.begin(), a.end(), 0); iota(b.begin(), b.end(), 0); function<int(vector<int>&, int)> f = [&](vector<int>& p, int x) { return p[x] == x ? x : p[x] = f(p, p[x]); }; for (int i = 0; i < m1; i++) { int u, w; in >> u >> w; a[f(a, u)] = f(a, w); } for (int i = 0; i < m2; i++) { int u, w; in >> u >> w; b[f(b, u)] = f(b, w); } int want, k; ans >> want; if (!(out >> k) || k != want) return 1; for (int i = 0; i < k; i++) { int u, w; if (!(out >> u >> w) || u < 1 || w < 1 || u > n || w > n) return 1; if (f(a, u) == f(a, w) || f(b, u) == f(b, w)) return 1; a[f(a, u)] = f(a, w); b[f(b, u)] = f(b, w); } return 0; }
